mapper.select:
SELECT
    wo.work_order_id, wo.work_order_no, wo.item_id, wo.equipment_id, wo.plan_qty, wo.start_date, wo.end_date, wo.status, wo.created_at,
    i.item_name, e.equipment_name
FROM work_order wo
JOIN item i ON i.item_id = wo.item_id
JOIN equipment e ON e.equipment_id = wo.equipment_id


    AND wo.status = #{status}


    AND wo.item_id = #{itemId}


    AND wo.equipment_id = #{equipmentId}


    AND wo.start_date = #{startDate}


    AND wo.end_date = #{endDate}


ORDER BY wo.work_order_id DESC

mapper.update:
UPDATE work_order
SET status = #{status}
WHERE work_order_id = #{workOrderId}
